(()=>{
const H=window.HBSTV,esc=escapeHtml,team=H.db.teams.find(t=>t.id==='iklegends');
const titles=H.db.events.filter(e=>e.year===2025&&e.winners.includes(team.id));
const c=team.logo.crop,logoHtml=`<span class="ik-cropped-logo"><img src="${team.logo.src}" alt="Logo da IK" style="width:${100/c.w}%;height:${100/c.h}%;left:${-100*c.x/c.w}%;top:${-100*c.y/c.h}%"></span>`;
window.renderIKArticle=()=>`<header class="hub-header"><span class="eyebrow">HBSTV · EQUIPES · TEMPORADA 2025</span><h2>IK em 2025: sete títulos e o topo do ranking</h2><p>4 de novembro de 2026 · A temporada da equipe número 1 do ano</p></header><article class="hub-article editorial-article"><p>Sete conquistas em três organizadoras e o primeiro lugar no ranking anual de equipes. A temporada de 2025 da IK combina volume de títulos com presença nas premiações individuais. Nos registros preservados pelo HBSTV, a equipe vence quatro campeonatos da BCN, duas ligas da LCS e a Master League da XMS.</p><div class="ik-article-summary">${logoHtml}<div><strong>IK · 2025</strong><span>7 títulos registrados · #1 no ranking anual</span></div></div><h3>Quatro conquistas na BCN</h3><p>A força da IK na temporada aparece nos títulos da Strike Cup, Yalla Compass, League e Finals. São quatro troféus da BCN no mesmo ano, formando a maior parte da coleção de conquistas de 2025 documentada no perfil da equipe.</p><p>As premiações dessas edições também destacam nomes presentes nos elencos campeões. ZDR é o MVP da Strike Cup. tabsenn recebe o prêmio de MVP na League e na Yalla Compass. Nas Finals, o título coletivo fica com a IK, enquanto o MVP registrado é T10.</p><h3>O domínio se estende à LCS e à XMS</h3><p>Na LCS, a IK soma as temporadas 1 e 2 da League. Na primeira edição, tabsenn aparece novamente como MVP. Na XMS, a conquista da Master League vem acompanhada de mais um prêmio de MVP para ZDR.</p><p>Entre esses sete títulos, há três prêmios de MVP para tabsenn e dois para ZDR. A ficha da LCS League S2 registra a conquista da equipe, mas ainda não detalha a escalação nem as premiações individuais.</p><h3>Os sete títulos da temporada</h3><div class="ik-title-list">${titles.map(e=>`<a href="${H.eventHref(e.id)}">${window.renderOrganizationEmblem(e.title)}<span><strong>${esc(e.title)}</strong><small>2025 · Campeã: IK</small></span><b aria-hidden="true">↗</b></a>`).join('')}</div><h3>Uma temporada construída por diferentes elencos</h3><p>Os registros dos campeonatos mostram mudanças nas escalações ao longo do ano. tabsenn, ZDR e Marvywn aparecem nos seis títulos com elenco detalhado. Entre os demais nomes presentes nas conquistas estão insani, c0njure, misuuta, Neguin, Jeff, Almeida e Hardzera. Cada ficha permite consultar os jogadores registrados naquela edição.</p><p>O resultado coletivo acompanha o destaque individual: tabsenn termina como #1 no Top 20 de 2025, seguido por ZDR em #2. No ranking de equipes, a IK fecha a temporada em primeiro lugar. Os títulos e as posições anuais sustentam o retrato de uma das grandes campanhas do histórico competitivo preservado no site.</p><div class="editorial-actions"><a class="hub-button" href="#time/iklegends">Explorar histórico da IK ↗</a><a class="hub-button" href="#acervo/top-1-teams-of-years">Ver equipes do ano ↗</a></div><p class="hub-note">Fontes: fichas dos campeonatos de 2025, ranking anual de equipes e Top 20 de jogadores preservados no HBSTV. Os sete títulos correspondem aos registros disponíveis; não representam uma contagem de todos os torneios disputados.</p></article>`;
const first=document.querySelector('.editorial-banner');
const carousel=document.createElement('section');carousel.className='editorial-carousel';carousel.setAttribute('aria-label','Matérias em destaque');carousel.setAttribute('aria-roledescription','carrossel');
const track=document.createElement('div');track.className='editorial-track';
first.before(carousel);track.append(first);carousel.append(track);
const second=document.createElement('a');second.className='editorial-banner ik-banner';second.href='#noticia/ik-legends-2025';second.innerHTML=`<div class="editorial-copy"><span class="eyebrow">DESTAQUE · EQUIPES DO ANO</span><h2>IK em 2025.<br>Sete títulos. Um ano no topo.</h2><p>Quatro conquistas na BCN, duas na LCS e uma na XMS. Conheça a campanha da equipe #1 do ano.</p><strong>Ler a matéria ↗</strong></div><div class="editorial-art ik-art" aria-hidden="true">${logoHtml}<span>#1 · EQUIPE DO ANO</span></div><div class="editorial-years"><span><small>BCN</small><b>4 títulos</b></span><span><small>LCS</small><b>2 títulos</b></span><span><small>XMS</small><b>1 título</b></span></div>`;track.append(second);
carousel.insertAdjacentHTML('beforeend','<div class="editorial-controls"><button type="button" data-slide-prev aria-label="Matéria anterior">←</button><div role="group" aria-label="Escolher matéria"><button type="button" data-slide="0" aria-label="Matéria de 4i20">1</button><button type="button" data-slide="1" aria-label="Matéria da IK">2</button></div><button type="button" data-slide-next aria-label="Próxima matéria">→</button><button type="button" data-slide-pause aria-pressed="false">Pausar</button><span class="editorial-slide-status" aria-live="off"></span></div>');
const slides=[first,second],reduce=matchMedia('(prefers-reduced-motion: reduce)');let current=0,paused=reduce.matches,hover=false,focused=false;
function show(i){current=(i+slides.length)%slides.length;track.style.setProperty('--slide',current);slides.forEach((s,n)=>{s.hidden=false;s.inert=n!==current;s.setAttribute('aria-hidden',String(n!==current));});carousel.querySelectorAll('[data-slide]').forEach((b,n)=>b.setAttribute('aria-pressed',String(n===current)));carousel.querySelector('.editorial-slide-status').textContent=(current+1)+' / '+slides.length;}
const pause=carousel.querySelector('[data-slide-pause]');function updatePause(){pause.textContent=paused?'Reproduzir':'Pausar';pause.setAttribute('aria-pressed',String(paused));}updatePause();
carousel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-slide'))show(+b.dataset.slide);if(b.hasAttribute('data-slide-next'))show(current+1);if(b.hasAttribute('data-slide-prev'))show(current-1);if(b.hasAttribute('data-slide-pause')){paused=!paused;updatePause();}});
carousel.addEventListener('pointerenter',()=>hover=true);carousel.addEventListener('pointerleave',()=>hover=false);carousel.addEventListener('focusin',()=>focused=true);carousel.addEventListener('focusout',e=>focused=carousel.contains(e.relatedTarget));
let touchX;track.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});track.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>45)show(current+(dx<0?1:-1));},{passive:true});
setInterval(()=>{if(!paused&&!hover&&!focused&&!document.hidden&&!carousel.hidden)show(current+1);},7000);
reduce.addEventListener('change',e=>{if(e.matches){paused=true;updatePause();}});
function route(){carousel.hidden=!!location.hash&&location.hash!=='#inicio';show(current);}window.addEventListener('hashchange',route);route();
})();
